using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ActorSceneExportOperations
{
    public Settings prepare(Control editor,string destination,int width,int height,int fps,Settings options)
    {
        Settings Failure(string error)=>new(){["error"]=error};string encoder=GD.Load<CSharpScript>("res://scripts/actors/core/ActorVideo.cs").Call("executable","ffmpeg").AsString();if(encoder.Length==0)return Failure("FFmpeg is required to export an MP4 video.");var viewport=editor.GetNodeOrNull<SubViewport>("../../../../World/SubViewport");if(viewport==null)return Failure("The scene viewport is unavailable.");var holder=editor.Get("runtime_holder").As<Node>();if(!GodotObject.IsInstanceValid(holder))return Failure("Scene actors are not ready to render.");if(destination.Length==0)return Failure("Choose an output file.");if(width<1||height<1||fps<1)return Failure("Frame dimensions and frame rate must be positive.");string output=ProjectSettings.GlobalizePath(destination);if(!DirAccess.DirExistsAbsolute(output.GetBaseDir()))return Failure("The output directory does not exist.");int samples=Math.Clamp(options.GetValueOrDefault("motion_samples",1).AsInt32(),1,8);double shutter=Math.Clamp(options.GetValueOrDefault("shutter",.5).AsDouble(),0,1);if(!double.IsFinite(shutter))return Failure("The shutter value must be finite.");if(shutter<=0)samples=1;if(fps>int.MaxValue/samples)return Failure("The frame rate is invalid.");double frames=Math.Max(1,Math.Ceiling(editor.Get("video_duration").AsDouble()*fps));if(!double.IsFinite(frames)||frames>int.MaxValue/samples)return Failure("The video duration or frame count is invalid.");string directory=ProjectSettings.GlobalizePath("user://scene_export/"+_data.new_id());if(DirAccess.MakeDirRecursiveAbsolute(directory)!=Error.Ok)return Failure("Could not create temporary frame directory.");var canvas=editor.Get("canvas").AsGodotObject();var fallback=viewport.GetNodeOrNull<Camera3D>("Freecam/Head/Camera3D");var oldCamera=viewport.GetCamera3D();var job=new Settings{["error"]="",["encoder"]=encoder,["viewport"]=viewport,["output"]=output,["frame_directory"]=directory,["frame_count"]=(int)frames,["samples"]=samples,["shutter"]=shutter,["fps"]=fps,["input_count"]=(int)frames*samples,["previous_sample"]=0.0,["old_time"]=canvas.Get("playhead"),["old_playing"]=editor.Get("playing"),["old_size"]=viewport.Size,["old_update"]=(int)viewport.RenderTargetUpdateMode,["old_msaa"]=viewport.Get("msaa_3d"),["old_growth_quality"]=viewport.HasMeta("kiwi_final_growth")?viewport.GetMeta("kiwi_final_growth"):default,["old_capture"]=viewport.HasMeta("kiwi_scene_frame_capture")?viewport.GetMeta("kiwi_scene_frame_capture"):default,["old_camera"]=oldCamera!=null?Variant.From(oldCamera):default,["free_camera"]=fallback!=null?Variant.From(fallback):default,["old_free_mask"]=fallback!=null?fallback.CullMask:1};if(options.TryGetValue("msaa",out var msaa))viewport.Set("msaa_3d",Math.Clamp(msaa.AsInt32(),0,3));viewport.SetMeta("kiwi_final_growth",true);viewport.SetMeta("kiwi_scene_frame_capture",true);var particles=new GArray();foreach(string type in new[]{"GPUParticles3D","GPUParticles2D","CPUParticles3D","CPUParticles2D"})foreach(var node in holder!.FindChildren("*",type,true,false)){particles.Add(new Settings{["node"]=node,["speed"]=node.Get("speed_scale"),["active"]=false});node.Set("speed_scale",0.0);}job["particle_states"]=particles;editor.Set("playing",false);editor.Set("exporting",true);if(fallback!=null)fallback.CullMask=1;var play=editor.Get("play_button").As<Button>();if(play!=null)play.Text="▶";viewport.Size=new Vector2I(width,height);viewport.RenderTargetUpdateMode=SubViewport.UpdateMode.Always;return job;
    }
    public void begin_frame(Control editor,Settings job,int frame)=>editor.Get("canvas").AsGodotObject().Set("playhead",temporal_sample_time(frame,job["samples"].AsInt32(),job["fps"].AsInt32(),job["shutter"].AsDouble()));
    public void synchronize_frame(Control editor,Settings job)
    {
        var viewport=job["viewport"].As<SubViewport>();viewport.GetNodeOrNull<Node>("KiwiEnvironmentWorld")?.Call("_process",0.0);viewport.GetNodeOrNull<Node>("KiwiFogEnvironment")?.Call("_process",0.0);editor.Call("_update_camera_overlays");double time=editor.Get("canvas").AsGodotObject().Get("playhead").AsDouble();foreach(var item in job["particle_states"].AsGodotArray()){var state=item.AsGodotDictionary();var node=state["node"].As<Node>();if(!GodotObject.IsInstanceValid(node))continue;bool active=(node is Node3D spatial?spatial.IsVisibleInTree():node is CanvasItem canvas&&canvas.IsVisibleInTree())&&node.Get("emitting").AsBool();if(active&&!state["active"].AsBool())node.Call("restart");if(active&&node.HasMethod("request_particles_process"))node.Call("request_particles_process",job["samples"].AsInt32()==1?1.0/job["fps"].AsInt32():Math.Max(0,time-job["previous_sample"].AsDouble()));state["active"]=active;}
    }
    public string save_frame(Control editor,Settings job,int frame){var image=job["viewport"].As<SubViewport>().GetTexture().GetImage();if(image==null||image.IsEmpty())return "The viewport returned an empty frame.";if(image.SavePng(job["frame_directory"].AsString().PathJoin("frame_"+frame.ToString("D6",System.Globalization.CultureInfo.InvariantCulture)+".png"))!=Error.Ok)return "Could not write a rendered frame.";job["previous_sample"]=editor.Get("canvas").AsGodotObject().Get("playhead");return "";}
    public void restore(Control editor,Settings job)
    {
        var viewport=job["viewport"].As<SubViewport>();viewport.Size=job["old_size"].AsVector2I();viewport.RenderTargetUpdateMode=(SubViewport.UpdateMode)job["old_update"].AsInt32();viewport.Set("msaa_3d",job["old_msaa"]);foreach(var pair in new[]{("old_growth_quality","kiwi_final_growth"),("old_capture","kiwi_scene_frame_capture")}){if(job[pair.Item1].VariantType==Variant.Type.Nil)viewport.RemoveMeta(pair.Item2);else viewport.SetMeta(pair.Item2,job[pair.Item1]);}var fallback=job["free_camera"].As<Camera3D>();if(fallback!=null)fallback.CullMask=job["old_free_mask"].AsUInt32();editor.Get("canvas").AsGodotObject().Set("playhead",job["old_time"]);editor.Set("playing",job["old_playing"]);editor.Set("exporting",false);var play=editor.Get("play_button").As<Button>();if(play!=null)play.Text=job["old_playing"].AsBool()?"Ⅱ":"▶";editor.Call("_evaluate_runtimes");if(fallback!=null)fallback.MakeCurrent();else{var camera=job["old_camera"].As<Camera3D>();if(GodotObject.IsInstanceValid(camera))camera!.MakeCurrent();}foreach(var item in job["particle_states"].AsGodotArray()){var state=item.AsGodotDictionary();var node=state["node"].As<Node>();if(!GodotObject.IsInstanceValid(node))continue;node.Set("speed_scale",state["speed"]);node.Call("restart");if(node.HasMethod("request_particles_process"))node.Call("request_particles_process",Math.Max(0,job["old_time"].AsDouble()));}
    }
}
